# Spot groups: cheaper machines AWS can take back, for routines that can simply retry.
# No Spot group for wide, and no warm pool.
resource "terraform_data" "spot_group" {
  for_each = { for k, v in var.sizes : k => v if k != "wide" }
  input = {
    name            = "${var.name_prefix}-sandbox-${each.key}-spot"
    launch_template = local_file.launch_template[each.key].filename
    instance_types  = [for family in ["m8i", "m7i", "m6i"] : replace(each.value, "m8i", family)]
    on_demand_pct   = 0
  }
}

output "spot_group_names" {
  value = { for size, g in terraform_data.spot_group : size => g.input.name }
}

# tests/pool.tftest.hcl (added at the end)
run "no_spot_group_for_wide" {
  command = plan

  variables {
    sizes          = { lite = "m8i.xlarge", full = "m8i.2xlarge", wide = "m8i.4xlarge" }
    warm_pool_size = { lite = 2, full = 2, wide = 0 }
  }

  assert {
    condition     = keys(terraform_data.spot_group) == ["full", "lite"]
    error_message = "Spot groups are for lite and full only."
  }
}
